import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
const root = process.argv[2];
process.env.DATA_DIR = root;
process.env.CACHE_DIR = path.join(root, 'cache');
process.env.ENV_USER_PATH = path.join(root, '.env');
process.env.GHARMONIZE_MASTER_KEY_FILE = path.join(root, '.key');
process.env.GHARMONIZE_ACCESS_MODE = 'admin';
process.env.GHARMONIZE_WEB_BINARIES = '0';
const { hashPassword } = await import('../../modules/security.js');
process.env.ADMIN_PASSWORD_HASH = hashPassword('FixturePassword9');
const { default: express } = await import('express');
const { default: settings, appAccessMiddleware } = await import('../../modules/settings.js');
const { default: router } = await import('../../routes/jobs.js');
const { createJob } = await import('../../modules/store.js');
const { setTrackStage } = await import('../../modules/jobTiming.js');
const j = createJob();
for (let i = 0; i < 120; i++) setTrackStage(j, `track:${i}`, 'downloading', { title: `Track ${i}`, localPath: '/private' });
const app = express();
app.use(express.json());
app.use(appAccessMiddleware);
app.use(router);
app.use('/api', settings);
const server = app.listen(0, '127.0.0.1');
await new Promise(resolve => server.once('listening', resolve));
const base = `http://127.0.0.1:${server.address().port}`;
try {
  const url = `${base}/api/jobs/${j.id}/timing`;
  assert.equal((await fetch(url)).status, 401);
  const login = await fetch(`${base}/api/auth/login`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ password: 'FixturePassword9' }) });
  assert.equal(login.status, 200);
  const headers = { cookie: login.headers.get('set-cookie').split(';')[0] };
  const response = await fetch(`${url}?offset=50&limit=999`, { headers });
  assert.equal(response.status, 200);
  const { timing } = await response.json();
  assert.equal(timing.offset, 50);
  assert.equal(timing.limit, 100);
  assert.equal(timing.tracks.length, 70);
  assert.equal(timing.tracks[0].key, 'track:50');
  assert.ok(!JSON.stringify(timing).includes('/private'));
  assert.equal((await fetch(`${base}/api/jobs/missing/timing`, { headers })).status, 404);
  const controller = new AbortController();
  const stream = await fetch(`${base}/api/stream`, { headers, signal: controller.signal });
  const reader = stream.body.getReader();
  let text = '';
  while (!text.includes('data:')) text += new TextDecoder().decode((await reader.read()).value);
  const data = JSON.parse(text.split('data: ')[1].split('\n')[0]);
  assert.equal(data.items[0].timing.trackCount, 120);
  assert.ok(data.items[0].timing.tracks.length <= 24);
  controller.abort();
  console.log('JOB_TIMING_API_OK');
} finally { server.close(); }
process.exit(0);
